#!/usr/bin/env node
/**
 * install-hooks.mjs — opt-in local guard: run the worklog checks before every commit.
 *
 * The `.worklog/` directory (todo files + generated roadmap.html) is gitignored, so CI
 * can never see a broken todo line. This installs a `.git/hooks/pre-commit` that runs
 * `roadmap.mjs --check` (and `scripts/check-todo-owners.mjs` when the repository has it)
 * and blocks the commit when they fail.
 *
 * Safety:
 *   - `--help` writes nothing.
 *   - default is dry-run; only `--apply` writes, and only `--uninstall` removes.
 *   - a hook that exists but was not generated by this tool is refused; `--force`
 *     backs the old file up to `.bak-<timestamp>` before overwriting.
 *   - the hook is local only: no network, no global git config changes.
 *
 * Usage:
 *   node skills/worklog/scripts/install-hooks.mjs            # dry-run
 *   node skills/worklog/scripts/install-hooks.mjs --apply
 *   node skills/worklog/scripts/install-hooks.mjs --force --apply
 *   node skills/worklog/scripts/install-hooks.mjs --uninstall
 *   node skills/worklog/scripts/install-hooks.mjs --repo <dir>
 *
 * Worktrees: each worktree has its own .git/hooks directory, so install once per
 * worktree. The hook runs in the repository root and only checks local files.
 */
import { chmodSync, copyFileSync, existsSync, readFileSync, statSync, unlinkSync, writeFileSync } from 'node:fs'
import { execFileSync } from 'node:child_process'
import path from 'node:path'
import process from 'node:process'

const MARKER = '# generated by skills/worklog/scripts/install-hooks.mjs'
const USAGE = `install-hooks.mjs — install .git/hooks/pre-commit for the worklog checks

Usage:
  node skills/worklog/scripts/install-hooks.mjs              dry-run (default): print the target and a summary
  node skills/worklog/scripts/install-hooks.mjs --apply      write the hook
  node skills/worklog/scripts/install-hooks.mjs --force --apply
  node skills/worklog/scripts/install-hooks.mjs --uninstall  remove the generated hook
  node skills/worklog/scripts/install-hooks.mjs --repo <dir> use another repository (default: git root)

The hook runs:
  node <repo>/skills/worklog/scripts/roadmap.mjs --check --worklog-dir <repo>/.worklog --out <repo>/../ROADMAP.md
  node <repo>/scripts/check-todo-owners.mjs        (only when that file exists)
and exits non-zero when either fails, so a todo line missing 验收/状态/归属/功能
cannot be committed unnoticed. Local only: no network, no global git config change.
Each worktree needs its own install. An existing hook not generated by this tool is
refused; --force backs it up to .bak-<timestamp> first.`

function parseArgs(argv) {
  const options = { apply: false, force: false, uninstall: false, help: false, repo: null }
  for (let index = 0; index < argv.length; index += 1) {
    const arg = argv[index]
    const value = () => {
      if (argv[index + 1] === undefined) fail(2, `${arg} requires a value\n\n${USAGE}`)
      index += 1
      return argv[index]
    }
    if (arg === '-h' || arg === '--help') options.help = true
    else if (arg === '--apply') options.apply = true
    else if (arg === '--force') options.force = true
    else if (arg === '--uninstall') options.uninstall = true
    else if (arg === '--repo') options.repo = value()
    else fail(2, `unknown argument: ${arg}\n\n${USAGE}`)
  }
  return options
}

function fail(code, message) {
  console.error(message)
  process.exit(code)
}

function gitRoot(repo) {
  const cwd = repo ? path.resolve(repo) : process.cwd()
  try {
    return execFileSync('git', ['rev-parse', '--show-toplevel'], { cwd, encoding: 'utf8' }).trim()
  } catch (error) {
    fail(2, `not a git repository (${cwd}): ${error.message}`)
  }
}

function hookContent(root) {
  const roadmap = path.join(root, 'skills', 'worklog', 'scripts', 'roadmap.mjs').replace(/\\/g, '/')
  const owners = path.join(root, 'scripts', 'check-todo-owners.mjs').replace(/\\/g, '/')
  return `#!/bin/sh
${MARKER}
# Local guard installed by the worklog skill. Remove with:
#   node skills/worklog/scripts/install-hooks.mjs --uninstall
set -e
ROOT=$(git rev-parse --show-toplevel)
if [ -d "$ROOT/.worklog/todo" ]; then
  node "$ROOT/skills/worklog/scripts/roadmap.mjs" --check --worklog-dir "$ROOT/.worklog" --out "$ROOT/../ROADMAP.md" || {
    echo "✗ .worklog/todo 校验未通过：提交已阻止；先修错误再重跑 roadmap --write" >&2
    exit 1
  }
fi
if [ -f "$ROOT/scripts/check-todo-owners.mjs" ]; then
  node "$ROOT/scripts/check-todo-owners.mjs" || {
    echo "✗ todo 归属校验未通过：提交已阻止" >&2
    exit 1
  }
fi
exit 0
`
}

function main() {
  const options = parseArgs(process.argv.slice(2))
  if (options.help) {
    console.log(USAGE)
    return 0
  }
  const root = gitRoot(options.repo)
  const hooksDir = path.join(root, '.git', 'hooks')
  const hookPath = path.join(hooksDir, 'pre-commit')

  if (options.uninstall) {
    if (!existsSync(hookPath)) {
      console.log(`nothing to remove: ${hookPath} does not exist`)
      return 0
    }
    if (!readFileSync(hookPath, 'utf8').includes(MARKER)) {
      fail(1, `refusing to remove ${hookPath}: not installed by this tool`)
    }
    unlinkSync(hookPath)
    console.log(`removed -> ${hookPath}`)
    return 0
  }

  const content = hookContent(root)
  const exists = existsSync(hookPath)
  const current = exists ? readFileSync(hookPath, 'utf8') : null
  const isOurs = current !== null && current.includes(MARKER)
  const summary = `hook=${hookPath}\nmarket=${MARKER}\nruns=roadmap --check${existsSync(path.join(root, 'scripts', 'check-todo-owners.mjs')) ? ' + check-todo-owners' : ''}`

  if (exists && !isOurs && !options.force) {
    fail(1, `refusing to overwrite ${hookPath}: it exists and was not generated by this tool; pass --force to back it up (.bak-<timestamp>) and replace it`)
  }
  if (exists && isOurs && current === content) {
    console.log(`already installed and up to date -> ${hookPath}`)
    return 0
  }

  if (!options.apply) {
    console.log(`${summary}\n${exists ? 'would replace the existing hook' : 'would create the hook'}${options.force && exists && !isOurs ? ' (backing up the old file first)' : ''}\nrun with --apply to write (dry-run, nothing written)`)
    return 0
  }

  if (exists && !isOurs) {
    const stamp = new Date().toISOString().replace(/[-:.TZ]/g, '').slice(0, 14)
    const backup = `${hookPath}.bak-${stamp}`
    copyFileSync(hookPath, backup)
    console.log(`backed up -> ${backup}`)
  }
  writeFileSync(hookPath, content, 'utf8')
  try {
    chmodSync(hookPath, 0o755)
  } catch {
    /* Windows: git runs hooks through sh; the executable bit is not required */
  }
  console.log(`installed -> ${hookPath}`)
  console.log(summary)
  return 0
}

try {
  process.exitCode = main()
} catch (error) {
  console.error(`ERROR ${error?.message ?? error}`)
  process.exitCode = 1
}
